export const optimizeRoutesBodyOptimizationWeightsDistanceWeightMin = 0;
export const optimizeRoutesBodyOptimizationWeightsDistanceWeightMax = 1;

export const optimizeRoutesBodyOptimizationWeightsCo2WeightDefault = 0.25;
export const optimizeRoutesBodyOptimizationWeightsCo2WeightMin = 0;
export const optimizeRoutesBodyOptimizationWeightsCo2WeightMax = 1;

export const optimizeRoutesBodyOptimizationWeightsEtaPrecisionWeightDefault = 0.15;
export const optimizeRoutesBodyOptimizationWeightsEtaPrecisionWeightMin = 0;
export const optimizeRoutesBodyOptimizationWeightsEtaPrecisionWeightMax = 1;

export const optimizeRoutesBodyOptimizationWeightsDriverHappinessWeightDefault = 0.15;
export const optimizeRoutesBodyOptimizationWeightsDriverHappinessWeightMin = 0;
