export const optimizeRoutesBodyPlanningInputsTravelReservePercentMax = 100;

export const optimizeRoutesBodyPlanningInputsStopReserveMinMin = 0;
export const optimizeRoutesBodyPlanningInputsStopReserveMinMax = 120;

export const optimizeRoutesBodyPlanningInputsExcludedPairValuesItemRegExp =
  new RegExp("^[0-9a-fA-F-]{36}:[0-9a-fA-F-]{36}$");
export const optimizeRoutesBodyPlanningInputsExcludedPairValuesMax = 50;

export const optimizeRoutesBodyPlanningInputsDepotOverrideTwoVerifiedDepotIdRegExp =
  new RegExp("^(organization-default|route:[0-9a-fA-F-]{36})$");
export const optimizeRoutesBodyPlanningInputsMaxDriverOvertimeMinMin = 0;
export const optimizeRoutesBodyPlanningInputsMaxDriverOvertimeMinMax = 1440;

export const optimizeRoutesBodyPlanningInputsAllowLateStopsMinMin = 0;
export const optimizeRoutesBodyPlanningInputsAllowLateStopsMinMax = 1440;

export const OptimizeRoutesBody = zod.object({
  organizationId: zod.guid(),
  vehicleIds: zod.array(zod.guid()),
  stopIds: zod.array(zod.guid()),
  depotLatitude: zod.number(),
  depotLongitude: zod.number(),
  timeBudgetMs: zod
    .number()
    .min(optimizeRoutesBodyTimeBudgetMsMin)
    .max(optimizeRoutesBodyTimeBudgetMsMax)
    .optional(),
  async: zod
    .boolean()
    .optional()
    .describe(
      "Run the optimization asynchronously. The web client uses this for large selections so progress can be displayed while the job runs.",
    ),
  vehicleDistributionMode: zod
    .enum(["minimize", "balance"])
    .default(optimizeRoutesBodyVehicleDistributionModeDefault)
    .describe(
      "Minimize active vehicles or balance estimated work time across all selected vehicles.",
    ),
  optimizationWeights: zod
    .object({
      distanceWeight: zod
        .number()
        .min(optimizeRoutesBodyOptimizationWeightsDistanceWeightMin)
        .max(optimizeRoutesBodyOptimizationWeightsDistanceWeightMax)
        .default(optimizeRoutesBodyOptimizationWeightsDistanceWeightDefault),
      co2Weight: zod
        .number()
        .min(optimizeRoutesBodyOptimizationWeightsCo2WeightMin)
        .max(optimizeRoutesBodyOptimizationWeightsCo2WeightMax)
        .default(optimizeRoutesBodyOptimizationWeightsCo2WeightDefault),
      etaPrecisionWeight: zod
        .number()
        .min(optimizeRoutesBodyOptimizationWeightsEtaPrecisionWeightMin)
        .max(optimizeRoutesBodyOptimizationWeightsEtaPrecisionWeightMax)
        .default(
          optimizeRoutesBodyOptimizationWeightsEtaPrecisionWeightDefault,
        ),
      driverHappinessWeight: zod
        .number()
        .min(optimizeRoutesBodyOptimizationWeightsDriverHappinessWeightMin)
        .max(optimizeRoutesBodyOptimizationWeightsDriverHappinessWeightMax)
        .default(
          optimizeRoutesBodyOptimizationWeightsDriverHappinessWeightDefault,
        ),
      geographicCohesionWeight: zod
        .number()
        .min(optimizeRoutesBodyOptimizationWeightsGeographicCohesionWeightMin)
        .max(optimizeRoutesBodyOptimizationWeightsGeographicCohesionWeightMax)
        .default(
          optimizeRoutesBodyOptimizationWeightsGeographicCohesionWeightDefault,
        )
        .describe(
          "Prefer keeping customer stops within 10 km on the same active route.",
        ),
    })
    .optional()
    .describe("Relative preferences used for feasible route candidates."),
  planningInputs: zod
    .object({
      version: zod.literal(1),
      objective: zod
        .enum([
          "balanced",
          "shortest",
          "geographic",
          "areas_worktime",
          "minimize_vehicles",
        ])
        .describe(
          "areas_worktime prioritizes coverage within shifts, then geographic neighborhood separation, then balanced driving plus service time, with road distance as a tie-breaker. Whole-plan multi-vehicle repartition is required to change areas; route-only sequencing cannot repartition stops. No zero-crossing guarantee.",
        ),
      travelReservePercent: zod
        .number()
        .min(optimizeRoutesBodyPlanningInputsTravelReservePercentMin)
        .max(optimizeRoutesBodyPlanningInputsTravelReservePercentMax),
      stopReserveMin: zod
        .int()
        .min(optimizeRoutesBodyPlanningInputsStopReserveMinMin)
        .max(optimizeRoutesBodyPlanningInputsStopReserveMinMax),
      stopPriorities: zod.record(
        zod.string(),
        zod.union([zod.literal(0), zod.literal(1), zod.literal(2)]),
      ),
      excludedPairValues: zod
        .array(
          zod
            .string()
            .regex(
              optimizeRoutesBodyPlanningInputsExcludedPairValuesItemRegExp,
            ),
        )
        .max(optimizeRoutesBodyPlanningInputsExcludedPairValuesMax),
      depotOverride: zod.union([
        zod.null(),
        zod.object({
          scope: zod.enum(["plan", "pair"]),
          vehicleId: zod.guid().optional(),
          verifiedDepotId: zod
            .string()
            .regex(
              optimizeRoutesBodyPlanningInputsDepotOverrideTwoVerifiedDepotIdRegExp,
            )
            .describe(
              "organization-default or route:{UUID}, where the latter reuses an immutable provider-verified route depot snapshot.",
            ),
        }),
      ]),
      vehicleSelectionMode: zod.enum([
        "use_all_selected_pairs",
        "minimize_vehicles",
      ]),
      maxDriverOvertimeMin: zod
        .int()
        .min(optimizeRoutesBodyPlanningInputsMaxDriverOvertimeMinMin)
        .max(optimizeRoutesBodyPlanningInputsMaxDriverOvertimeMinMax)
        .optional(),
      allowLateStopsMin: zod
        .int()
        .min(optimizeRoutesBodyPlanningInputsAllowLateStopsMinMin)
        .max(optimizeRoutesBodyPlanningInputsAllowLateStopsMinMax)
        .optional(),
    })
    .optional(),
});

